INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(8080, 'koKR', 'Zasoby Kotliny Aratorskiej!', 'Każdy żołnierz ci powie, że wojnę toczy się żołnierzami. Powie ci też, że bitwa stoczona w kiepskim ekwipunku albo o pustym żołądku jest przegrana, zanim się zacznie!$B$BDlatego Kotlina Aratorska jest tak ważna. W kotlinie są kluczowe miejsca, w których znajdują się niezbędne zasoby. Metale, broń, żywność, drewno – wszystko to jest potrzebne i wszystko można tam zdobyć.$B$BTego właśnie od ciebie chcę, $N. Wejdź do Kotliny Aratorskiej, wygraj bitwę, utrzymując więcej baz niż wróg, i wróć do mnie ze skrzynią zasobów.', 'Wygraj bitwę o Kotlinę Aratorską, zdobądź aratorską skrzynię zasobów i zanieś ją sierżant Maclear w Punkcie Schronienia.', '', 'Wróć do sierżant Maclear w Punkcie Schronienia na Wyżynach Aratorskich.', '', '', '', '', 0),
(8123, 'koKR', 'Przetnij aratorskie linie zaopatrzenia', 'Liga Aratoru nie szczędzi środków, by odbić Arathi. Jej członkowie, a wraz z nimi wszystkie rasy Przymierza, ściągają teraz w ten odległy region, chcąc rozszerzyć swoje wpływy poza Punkt Schronienia. Musimy ich powstrzymać, a najlepszym sposobem jest odebranie im zaopatrzenia.$B$BMożesz nam pomóc, $N. Wejdź do Kotliny Aratorskiej, słynącej z bogatych kopalni, żyznej ziemi i zdolnych rzemieślników. Zdobądź i utrzymaj tyle baz, ile zdołasz, wygraj bitwę i wróć do mnie ze zdobytymi zasobami.', 'Wygraj bitwę o Kotlinę Aratorską, zdobądź aratorską skrzynię zasobów i zanieś ją tropicielowi śmierci Mortisowi w Młotogrodzie.', '', 'Wróć do tropiciela śmierci Mortisa w Kręgu Wschodniego Spętania na Wyżynach Aratorskich.', '', '', '', '', 0),
(8154, 'koKR', 'Zasoby Kotliny Aratorskiej!', 'Każdy żołnierz ci powie, że wojnę toczy się żołnierzami. Powie ci też, że bitwa stoczona w kiepskim ekwipunku albo o pustym żołądku jest przegrana, zanim się zacznie!$B$BDlatego Kotlina Aratorska jest tak ważna. W kotlinie są kluczowe miejsca, w których znajdują się niezbędne zasoby. Metale, broń, żywność, drewno – wszystko to jest potrzebne i wszystko można tam zdobyć.$B$BTego właśnie od ciebie chcę, $N. Wejdź do Kotliny Aratorskiej, wygraj bitwę, utrzymując więcej baz niż wróg, i wróć do mnie ze skrzynią zasobów.', 'Wygraj bitwę o Kotlinę Aratorską, zdobądź aratorską skrzynię zasobów i zanieś ją sierżant Maclear w Punkcie Schronienia.', '', 'Wróć do sierżant Maclear w Punkcie Schronienia na Wyżynach Aratorskich.', '', '', '', '', 0),
