INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(8080, 'koKR', 'Masz zasoby! Świetna robota! Wyślę je naszym kwatermistrzom, którzy szybko rozdzielą je między nasze oddziały.$B$BDziękuję ci, $N. To właśnie dzięki udanym misjom, takim jak twoja, naprawdę wygrywa się wojny.', 0),
